    [408245] = { en = "Heals the target over 7 sec.  When Lifebloom completes its duration or is dispelled, the target instantly heals.  This effect can stack up to 3 times on the same target.", description = "Cura il bersaglio per 7 s.  Quando Fioritura della Vita termina o viene dissolta, il bersaglio riceve una cura istantanea.  Questo effetto può accumularsi fino a 3 volte sullo stesso bersaglio." },
    [425421] = { en = "Your Charge, Intercept, and Intervene abilities are now usable while in combat and in any stance, and will all remove movement impairing effects when activated.", description = "Le abilità Carica, Intercetta e Intervento possono ora essere usate in combattimento e in qualsiasi postura; quando vengono attivate, rimuovono anche gli effetti che limitano il movimento." },
    [425464] = { en = "Your Demonic Sacrifice effect is no longer cancelled by summoning a different Demon pet. Resummoning the sacrificed pet will still cancel the effect.\r\n", description = "L'effetto del tuo Sacrificio Demoniaco non viene più annullato evocando un demone diverso. Evocare nuovamente il demone sacrificato annullerà comunque l'effetto.\r\n" },
    [425713] = { en = "Your critical hits with Shot and Strike abilities and with Mongoose Bite cause your pet's next 2 special attacks to critically hit.", description = "I colpi critici con le abilità Tiro e Colpo e con Morso della Mangusta fanno sì che i prossimi 2 attacchi speciali della tua mascotte siano critici." },
    [426606] = { en = "Allows the imbiber to speak with the corpse of an individual with unfinished business in the mortal world. Also may cure indigestion.", description = "Permette a chi la beve di parlare con il cadavere di una persona che ha questioni irrisolte nel mondo dei mortali. Può anche curare l'indigestione." },
    [427733] = { en = "Summons a Felguard under the command of the Warlock.\r\n\r\nThe Felguard benefits from all talents and effects that trigger from or benefit any of your other Demon minions.", description = "Evoca un Vilguardiano al comando dello stregone.\r\n\r\nIl Vilguardiano beneficia di tutti i talenti e gli effetti che si attivano o avvantaggiano gli altri tuoi servitori demoniaci." },
    [430021] = { en = "Consider at a Thistlefur dreamcatcher high in the canopy to receive a prophecy.", description = "Medita presso un acchiappasogni dei Mantofituso, in alto tra le fronde, per ricevere una profezia." },
    [430392] = { en = "While applied to the target weapon increases Hit Chance by 2% for 30 minutes. This has no effect outside of Blackfathom Deeps.", description = "Applicato all'arma bersaglio, aumenta del 2% la probabilità di colpire per 30 minuti. Non ha effetto al di fuori di Blackfathom Deeps." },
    [430419] = { en = "Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?", description = "Decifra la pergamena con un Amuleto della Comprensione. Chissà quale magia contiene." },
    [430491] = { en = "Unlucky! Your total health has been reduced by 10% for 20 minutes.", description = "Che sfortuna! La tua salute massima è ridotta del 10% per 20 minuti." },
    [430492] = { en = "You feel invigorated! Your total health has been increased by 25% for 20 minutes.", description = "Ti senti pieno di energia! La tua salute massima è aumentata del 25% per 20 minuti." },
    [430493] = { en = "You feel unhealthy! Your natural health regen has been reduced by 100% for 20 minutes.", description = "Non ti senti in forma! La rigenerazione naturale della salute è ridotta del 100% per 20 minuti." },
    [430494] = { en = "You feel fast! Your movement speed has been increased by 50% for 20 minutes.", description = "Ti senti veloce! La velocità di movimento è aumentata del 50% per 20 minuti." },
    [430495] = { en = "You feel sluggish! Your movement speed has been decreased by 25% for 20 minutes.", description = "Ti senti fiacco! La velocità di movimento è ridotta del 25% per 20 minuti." },
    [430497] = { en = "Oh no! You've been demoted back to newbie!", description = "Oh no! Sei stato retrocesso al grado di novellino!" },
    [430499] = { en = "Oh no! You've been demoted back to newbie!", description = "Oh no! Sei stato retrocesso al grado di novellino!" },
    [430501] = { en = "You feel unsteady! ", description = "Ti senti instabile! " },
    [430947] = { en = "Increases hit chance of spells by 3%, critical chance of melee, and ranged by 2%, grants 20 attack power, 25 spell damage, and increases movement speed by 20%. 120 minute duration.", description = "Aumenta del 3% la probabilità di colpire con gli incantesimi, del 2% la probabilità di critico in mischia e a distanza, conferisce 20 potenza d'attacco e 25 danni magici e aumenta del 20% la velocità di movimento. Dura 120 minuti." },
    [431388] = { en = "Your Barkskin can now be cast on allies, no longer penalizes melee combat speed or spellcasting time, and can be cast while shapeshifted.", description = "Pelle Dura può ora essere lanciato sugli alleati, non penalizza più la velocità d'attacco in mischia né il tempo di lancio e può essere lanciato in forma mutata." },
    [432264] = { en = "When any player in your party critically hits with a spell or ability, you gain a combo point on your current target.  This effect cannot occur more than once every second.", description = "Quando un membro del tuo gruppo mette a segno un colpo critico con un incantesimo o un'abilità, ottieni un punto combo sul bersaglio attuale.  Questo effetto può attivarsi al massimo una volta al secondo." },
    [433551] = { en = "Give water to an ancient sapling.", description = "Dai da bere a un alberello antico." },
    [433813] = { en = "Your next Soul Shard consuming spell cost no Soul Shards to cast.", description = "Il prossimo incantesimo che consuma Frammenti d'Anima non ne richiede per essere lanciato." },
    [433883] = { en = "Transmute 100 Copper Blood Coins into 1 Silver Blood Coin.", description = "Trasmuta 100 Copper Blood Coins in 1 Silver Blood Coin." },
    [433884] = { en = "Transmute 100 Silver Blood Coins into 1 Gold Blood Coin.", description = "Trasmuta 100 Silver Blood Coins in 1 Gold Blood Coin." },
    [433887] = { en = "Receive tokens for your service to the Blood God.", description = "Ricevi dei gettoni per il tuo servizio al Blood God." },
    [434350] = { en = "Plant into Soft Soil.", description = "Pianta nel terreno morbido." },
    [434503] = { en = "Combine three Divine Prayer Beads to make a rosary.", description = "Combina tre Divine Prayer Beads per creare un rosario." },
    [434814] = { en = "Mix with the Tears of Theradras to create an Elemental Salve capable of purifying corruption.", description = "Mescola con le Tears of Theradras per creare un Elemental Salve in grado di purificare la corruzione." },
    [434827] = { en = "Pour over corrupted objects to cleanse them.", description = "Versa sugli oggetti corrotti per purificarli." },
    [434957] = { en = "Catch an exotic bug, and keep it as a specimen. ", description = "Cattura un insetto esotico e conservalo come esemplare. " },
    [434994] = { en = "Combine 10 Conjuror's Pendants and a Soul of the Void near a Void Prism.", description = "Combina 10 Conjuror's Pendants e una Soul of the Void vicino a un Void Prism." },
    [435117] = { en = "Share meditation with the target Priest.", description = "Condividi la meditazione con il sacerdote bersaglio." },
    [435120] = { en = "Focus on the Vision to learn a new spell.  Requires a glimpse of corrupt knowledge.", description = "Concentrati sulla Visione per apprendere un nuovo incantesimo.  È necessario aver intravisto una conoscenza corrotta." },
    [435213] = { en = "Combine 10 Strong Harpy Feathers and 3 Cloud Serpent Fangs with 1 Silken Thread to create an Offering to the Wind Spirit.", description = "Combina 10 Strong Harpy Feathers e 3 Cloud Serpent Fangs con 1 Silken Thread per creare un'offerta al Wind Spirit." },
    [435218] = { en = "Make an Offering to the Wind Spirit and show your faith.", description = "Fai un'offerta al Wind Spirit e dimostra la tua fede." },
    [435532] = { en = "The staff will sometimes be able to shock a dead player back to life.  Cannot be used when in combat.", description = "A volte il bastone può riportare in vita un giocatore morto con una scarica.  Non può essere usato in combattimento." },
    [435986] = { en = "Transfigures the caster into a Trogg.", description = "Trasforma l'incantatore in un trogg." },
    [436097] = { en = "The thirst for blood fills your senses!", description = "La sete di sangue pervade i tuoi sensi!" },
    [436278] = { en = "Strike the gong inside the Witherbark's den.", description = "Percuoti il gong nella tana dei Witherbark." },
    [436288] = { en = "Summons and dismisses a rideable Raptor.", description = "Evoca e congeda un raptor cavalcabile." },
    [436289] = { en = "Summons and dismisses a rideable Raptor.", description = "Evoca e congeda un raptor cavalcabile." },
    [436327] = { en = "Summons and dismisses a rideable Bengal Tiger.", description = "Evoca e congeda una tigre del Bengala cavalcabile." },
    [436329] = { en = "Summons and dismisses a rideable Golden Saber Cat.", description = "Evoca e congeda un Golden Saber Cat cavalcabile." },
    [436431] = { en = "Now you know you're being watched...", description = "Ora sai che qualcuno ti sta osservando..." },
    [436432] = { en = "Eat a handful and make up for lost time on the trail!", description = "Mangiane una manciata e recupera il tempo perso lungo il cammino!" },
    [436444] = { en = "Unrelenting, unprejudiced, and undamned. ", description = "Implacabile, imparziale e non dannato. " },
    [436534] = { en = "Thank you for your cooperation.", description = "Grazie per la collaborazione." },
    [436545] = { en = "Combine with an appropriate power source to create a Charged Voidcore.", description = "Combina con una fonte di energia adeguata per creare un Charged Voidcore." },
    [436623] = { en = "Dig up the buried cache at the marked location", description = "Dissotterra il deposito nel punto indicato." },
    [436641] = { en = "The thirst for blood fills your senses!", description = "La sete di sangue pervade i tuoi sensi!" },
