    [437424] = { en = "The caster focuses clouds of slumber around targets.", description = "L'incantatore concentra nubi soporifere attorno ai bersagli." },
    [437716] = { en = "Your next attack will critically strike.", description = "Il tuo prossimo attacco sarà un colpo critico." },
    [437751] = { en = "Bruised.", description = "Contuso." },
    [437765] = { en = "Instantly attack the target causing damage.", description = "Attacca istantaneamente il bersaglio, infliggendo danni." },
    [437877] = { en = "Ogom gains an infusion of Light.", description = "Ogom viene pervaso dalla Luce." },
    [437881] = { en = "Jammal'an gains an infusion of Shadow.", description = "Jammal'an viene pervaso dall'Ombra." },
    [437951] = { en = "Eats the target.", description = "Divora il bersaglio." },
    [437995] = { en = "Drains the target.", description = "Prosciuga il bersaglio." },
    [438045] = { en = "Transfers any existing combo points to the current non-player enemy target. Requires active combo points.\r\n", description = "Trasferisce tutti i punti combo accumulati al bersaglio nemico attuale, se non è un giocatore. Richiede punti combo attivi.\r\n" },
    [438105] = { en = "Gain 250 honor.", description = "Ottieni 250 punti onore." },
