    [444892] = { en = "You are siezed by darkness!", description = "Sei sopraffatto dalle tenebre!" },
    [444894] = { en = "A blast of Holy Power.", description = "Un'esplosione di potere sacro." },
    [445517] = { en = "Spits acid at a target, inflicting Nature damage.", description = "Sputa acido contro un bersaglio, infliggendo danni da natura." },
    [445558] = { en = "Throw out a hooked chain to restrain the target and pull them toward you.", description = "Scaglia una catena munita di uncino per immobilizzare il bersaglio e trascinarlo verso di te." },
    [446097] = { en = "The crystal resonates in response to the Nightmare.", description = "Il cristallo risuona in risposta all'Incubo." },
    [446098] = { en = "Perform an ancient Atal'ai hex upon yourself.", description = "Lancia su di te un'antica maledizione Atal'ai." },
    [446100] = { en = "Become Inanimate!", description = "Diventa inanimato!" },
    [446101] = { en = "A sacrificial dagger, engraved with a chant for an ancient Atal'ai blood ceremony.", description = "Un pugnale sacrificale inciso con un canto per un antico rito Atal'ai del sangue." },
    [446103] = { en = "Sacrifices have been made.", description = "I sacrifici sono stati compiuti." },
    [446104] = { en = "Focus your spirit into Atal'alarion's favorite boulder. Enchanted with the last echoes of his soul.", description = "Concentra il tuo spirito nel masso prediletto di Atal'alarion, incantato con gli ultimi echi della sua anima." },
    [446363] = { en = "Combine with 4 other pieces to rebuild Iodax.", description = "Combina con altri 4 frammenti per ricostruire Iodax." },
    [446451] = { en = "Permanently adds 15 attack power to a shoulder slot item.", description = "Aggiunge permanentemente 15 potenza d'attacco a un oggetto da spalle." },
    [446454] = { en = "Use 4 leycrysts to attune with Azeroth and learn a new ability.", description = "Usa 4 cristalli tellurici per sintonizzarti con Azeroth e apprendere una nuova abilità." },
    [446456] = { en = "Disguise yourself as a haggard Dark Iron Dwarf. Suspicious activity will break the disguise.", description = "Travestiti da Nano Ferroscuro dall'aspetto trasandato. Le azioni sospette riveleranno il travestimento." },
    [446459] = { en = "Permanently adds to a shoulder slot item increased damage and healing done by magical spells and effects by 9.", description = "Aumenta permanentemente di 9 i danni e le cure degli incantesimi e degli effetti magici di un oggetto da spalle." },
    [446472] = { en = "Permanently adds to a shoulder slot item increased healing done by spells and effects up to 18.", description = "Aumenta permanentemente fino a 18 le cure degli incantesimi e degli effetti di un oggetto da spalle." },
    [446504] = { en = "Blasts open difficult locked doors.", description = "Fa saltare le porte chiuse più resistenti." },
    [446509] = { en = "Present as an offering at the Shrine of the Beast.", description = "Presenta come offerta al Santuario della Bestia." },
    [446637] = { en = "Cleans your weapon. Removing all temporary enchants. Good as new!", description = "Pulisce la tua arma e rimuove tutti gli incantamenti temporanei. Come nuova!" },
    [446640] = { en = "Cleaned! Good as new!", description = "Pulita! Come nuova!" },
    [446672] = { en = "Transmute 100 Copper Massacre Coins into 1 Silver Massacre Coin.", description = "Trasmuta 100 Copper Massacre Coins in 1 Silver Massacre Coin." },
    [446674] = { en = "Transmute 100 Silver Massacre Coins into 1 Gold Massacre Coin.", description = "Trasmuta 100 Silver Massacre Coins in 1 Gold Massacre Coin." },
    [446676] = { en = "Receive tokens for your service to the Blood God.", description = "Ricevi dei gettoni per il tuo servizio al Blood God." },
    [446685] = { en = "Summons and dismisses a rideable Blood-crazed Spirit.", description = "Evoca e congeda uno Spirit cavalcabile in preda alla furia del sangue." },
    [446704] = { en = "Catch the attention of a Delirious Ancient, drawing it into combat.", description = "Attira l'attenzione di un Antico Delirante e trascinalo in combattimento." },
    [446806] = { en = "Hexes yourself to be a bit harder to detect in Sunken Temple.", description = "Ti lancia una maledizione per renderti un po' più difficile da individuare nel Sunken Temple." },
    [446891] = { en = "Summon the Spirit of Agamaggan. May only be used at the top of the Spiral of Thorns in Razorfen Downs, after defeating all nearby enemies.", description = "Evoca lo Spirit of Agamaggan. Può essere usato solo in cima alla Spiral of Thorns a Razorfen Downs, dopo aver sconfitto tutti i nemici vicini." },
    [447051] = { en = "A cipher is needed to understand the Warlock's notes. Who knows what magic it contains?", description = "Serve un cifrario per comprendere gli appunti dello stregone. Chissà quale magia contengono." },
    [447472] = { en = "Combine 3 Satyrweed samples to brew a tincture.", description = "Combina 3 campioni di Satyrweed per preparare una tintura." },
    [447475] = { en = "Cure a creature of Satyr corruption.", description = "Libera una creatura dalla corruzione dei satiri." },
    [447590] = { en = "Weaken Calefactus the Unleashed.", description = "Indebolisci Calefactus il Liberato." },
    [448149] = { en = "Learn a new Engraving ability.", description = "Apprendi una nuova abilità di Incisione." },
    [448415] = { en = "Become Inanimate!", description = "Diventa inanimato!" },
    [448614] = { en = "Don a bush, for whatever reason you may have.", description = "Indossa un cespuglio, qualunque sia il motivo." },
    [448618] = { en = "Find a use for all those empty supply crates.", description = "Trova un utilizzo per tutte quelle casse di rifornimenti vuote." },
    [448629] = { en = "You sometimes find additional Waylaid supplies from enemies.", description = "A volte trovi rifornimenti dirottati aggiuntivi sui nemici." },
    [450105] = { en = "Attempts to remove one Curse, one Disease and one Poison from the Imbiber.", description = "Tenta di rimuovere una maledizione, una malattia e un veleno da chi beve." },
    [452454] = { en = "Healed by successful blocks.", description = "Curato dai blocchi riusciti." },
    [452460] = { en = "Successful blocks cause an explosion of fire damage.", description = "I blocchi riusciti provocano un'esplosione di danni da fuoco." },
    [452466] = { en = "Summoned totems grant a boon of their element.", description = "I totem evocati conferiscono un beneficio del proprio elemento." },
    [453482] = { en = "Attune with the heavens, allowing you to replace your Moonkin form with a more celestial visage.", description = "Sintonizzati con i cieli per sostituire la forma di Moonkin con un aspetto più celestiale." },
    [454469] = { en = "Overcharge a Legion Portal Tuner.", description = "Sovraccarica un Legion Portal Tuner." },
    [455876] = { en = "Polish off the soot.", description = "Rimuovi la fuliggine lucidando." },
