    [455989] = { en = "A sweeping attack that strikes all enemies to the right of the caster.", description = "Un attacco ampio che colpisce tutti i nemici alla destra dell'incantatore." },
    [455991] = { en = "Discharge power with the impact of your stomp, knocking back and damaging nearby enemies.", description = "Scatena energia con l'impatto del tuo pestone, respingendo e danneggiando i nemici vicini." },
    [455994] = { en = "A sweeping attack that strikes all enemies in front of the caster.", description = "Un attacco ampio che colpisce tutti i nemici di fronte all'incantatore." },
    [456010] = { en = "Recover mana.", description = "Rigenera mana." },
