    [459261] = { en = "Capture the echo of a powerful denizen of Stratholme. Only usable on corpses.", description = "Cattura l'eco di un potente abitante di Stratholme. Utilizzabile solo sui cadaveri." },
    [459290] = { en = "Discharge power with the impact of your stomp, knocking back and damaging nearby enemies.", description = "Scatena energia con l'impatto del tuo pestone, respingendo e danneggiando i nemici vicini." },
    [459610] = { en = "Increases movement speed by 10% and all stats by 15% for 2 hours.", description = "Aumenta la velocità di movimento del 10% e tutte le statistiche del 15% per 2 ore." },
    [459615] = { en = "On landing a killing blow that grants experience or honor, your next attack will critically strike.", description = "Dopo aver inflitto un colpo mortale che assegna esperienza o onore, il tuo prossimo attacco sarà un colpo critico." },
    [459695] = { en = "Learn a Priest spell from another race to activate an ability in this slot.", description = "Apprendi un incantesimo da sacerdote di un'altra razza per attivare un'abilità in questo slot." },
    [460363] = { en = "Focus the Modified Shadow Scalpel on Arkonos the Cursed to dispel his barrier of protection.", description = "Punta lo Shadow Scalpel Modificato su Arkonos il Maledetto per dissolvere la sua barriera protettiva." },
    [460375] = { en = "Give Orthas' tooth a... rub. Gross.", description = "Strofina un po' il dente di Orthas... Che schifo." },
    [460749] = { en = "Inflicts Shadow damage to an enemy, but causes a high amount of threat.", description = "Infligge danni da ombra a un nemico, generando però molta minaccia." },
    [460923] = { en = "Decipher the scroll with a Comprehension Charm. Who knows what magic it contains?", description = "Decifra la pergamena con un Amuleto della Comprensione. Chissà quale magia contiene." },
    [460940] = { en = "Increases hitpoints by 300. 15% haste to melee attacks. 10 mana regen every 5 seconds.", description = "Aumenta i punti vita di 300. Aumenta del 15% la velocità d'attacco in mischia. Rigenera 10 mana ogni 5 secondi." },
    [461137] = { en = "Pledge fealty to the Waterlords!", description = "Giura fedeltà ai Waterlords!" },
    [461164] = { en = "2% chance on ranged hit to gain 1 extra attack.", description = "Ogni colpo a distanza ha una probabilità del 2% di fornire 1 attacco aggiuntivo." },
    [461196] = { en = "The increased temperatures in Blackrock Mountain have caused your blood to run Hot!", description = "Le alte temperature di Blackrock Mountain hanno fatto ribollire il tuo sangue!" },
    [461231] = { en = "Removes all harmful Magic Fire effects.", description = "Rimuove tutti gli effetti magici del Fuoco dannosi." },
    [461256] = { en = "Your presence is tolerated by the Alliance. For now.", description = "La tua presenza è tollerata dall'Alleanza. Per ora." },
    [461269] = { en = "Parley with an opposing Priest to gain safe passage through enemy territory.", description = "Tratta con un sacerdote avversario per attraversare in sicurezza il territorio nemico." },
    [461289] = { en = "Wards the bearer against the fel glamours surrounding Demon Fall Canyon.", description = "Protegge chi lo porta dagli incanti vili che circondano Demon Fall Canyon." },
    [461324] = { en = "Drink the Dreamjuice to enter a state of waking sleep, allowing you to see hidden enemies. Only usable in Thorium Point.", description = "Bevi il Dreamjuice per entrare in uno stato di sonno vigile e vedere i nemici nascosti. Utilizzabile solo a Thorium Point." },
    [461329] = { en = "Allows the caster to levitate, floating a few feet above the ground.  While levitating, you will fall at a reduced speed and travel over water-like surfaces.  ", description = "Permette all'incantatore di levitare a pochi centimetri dal suolo.  Mentre leviti, cadi più lentamente e puoi spostarti su superfici simili all'acqua." },
    [461330] = { en = "A sweeping attack that strikes all enemies to the left of the caster.", description = "Un attacco ampio che colpisce tutti i nemici alla sinistra dell'incantatore." },
    [461352] = { en = "Smashes the area in front of the caster.", description = "Devasta l'area di fronte all'incantatore." },
