    [462229] = { en = "When struck in combat has a chance of causing the attacker to flee in terror for 2 seconds. ", description = "Quando vieni colpito in combattimento, hai una probabilità di far fuggire l'attaccante terrorizzato per 2 secondi. " },
    [462238] = { en = "Exhausted.", description = "Sfinito." },
    [462467] = { en = "Recover mana.", description = "Rigenera mana." },
    [463005] = { en = "Summons and dismisses a rideable mechanical tallstrider.", description = "Evoca e congeda uno strider meccanico cavalcabile." },
    [463006] = { en = "Summons and dismisses a rideable Golden Saber Cat.", description = "Evoca e congeda un Golden Saber Cat cavalcabile." },
    [463007] = { en = "Summons and dismisses a rideable Raptor.", description = "Evoca e congeda un raptor cavalcabile." },
    [463555] = { en = "Receive tokens for your service to the Blood God.", description = "Ricevi dei gettoni per il tuo servizio al Blood God." },
    [463556] = { en = "Transmute 100 Copper Slaughter Coins into 1 Silver Slaughter Coin.", description = "Trasmuta 100 Slaughter Coins di Rame in 1 Slaughter Coin d'Argento." },
    [463557] = { en = "Transmute 100 Silver Massacre Coins into 1 Gold Massacre Coin.", description = "Trasmuta 100 Massacre Coins d'Argento in 1 Massacre Coin d'Oro." },
    [463868] = { en = "While applied to target shield it increases spell damage and healing by up to 24.  Lasts for 30 minutes.", description = "Applicato allo scudo bersaglio, aumenta fino a 24 i danni degli incantesimi e le cure.  Dura 30 minuti." },
    [463871] = { en = "Permanently enchant a Shield to add up to 30 damage to spells and up to 55 points of healing to healing spells.", description = "Incanta permanentemente uno scudo, aggiungendo fino a 30 danni agli incantesimi e fino a 55 punti di cura agli incantesimi curativi." },
    [466211] = { en = "Strikes enemies in a cone in front of the caster, knocking them back.", description = "Colpisce i nemici in un cono di fronte all'incantatore, respingendoli." },
    [466329] = { en = "Knock the enemy into the air with a quick uppercut.", description = "Scaglia in aria il nemico con un rapido montante." },
    [466841] = { en = "Throw out a hooked chain to restrain the target and pull them toward you.", description = "Scaglia una catena munita di uncino per immobilizzare il bersaglio e trascinarlo verso di te." },
    [467227] = { en = "Your Swipe now spreads your Lacerate from your primary target to other targets it strikes.", description = "Swipe diffonde ora Lacerate dal bersaglio primario agli altri bersagli colpiti." },
    [467365] = { en = "Knock the enemy into the air with a quick uppercut.", description = "Scaglia in aria il nemico con un rapido montante." },
    [467667] = { en = "The Shadowfiend's melee attacks siphon energy from the target, converting it into mana for its master.", description = "Gli attacchi in mischia del Demone Ombroso prosciugano energia dal bersaglio e la trasformano in mana per il padrone." },
}

for id, description in pairs(verifiedSpellDescriptions) do
    ns.data.spellDescriptionOverrides[id] = description
end
